GUIDE = [
 ('sos', T("Attivare l'SOS in caso di caduta", 'Switching on the fall SOS', "Activer le SOS en cas de chute", 'Den Sturz-SOS einschalten', 'Activar el SOS por caída'), T(
   ["Apri <b>Menu › Impostazioni › SOS in caso di caduta</b>.", "Scrivi il <b>tuo nome</b> e il <b>tuo numero</b> (serve a chi riceve l'SMS per richiamarti) e fino a <b>3 numeri da avvisare</b>.", "Concedi il permesso <b>SMS</b> quando Android lo chiede: serve solo a mandare l'avviso.", "Scegli la <b>sensibilità</b> (bassa, media, alta) e accendi l'interruttore.", "Premi <b>Prova SOS</b>: manda un messaggio di PROVA ai tuoi numeri, chiaramente indicato come test.", "Da ora, se vai oltre 25 km/h, c'è un urto forte e poi resti fermo, parte il conto alla rovescia di 30 secondi con sirena: tocca <b>Sto bene</b> per annullare."],
   ["Open <b>Menu › Settings › Fall SOS</b>.", "Write <b>your name</b> and <b>your number</b> (so the receiver can call you back) and up to <b>3 numbers to alert</b>.", "Grant the <b>SMS</b> permission when Android asks: it is used only to send the alert.", "Choose the <b>sensitivity</b> (low, medium, high) and switch it on.", "Press <b>Test SOS</b>: it sends a TEST message to your numbers, clearly marked as a test.", "From now on, if you are above 25 km/h, there is a hard impact and then you stay still, a 30-second countdown with a siren starts: tap <b>I'm fine</b> to cancel."],
   ["Ouvre <b>Menu › Réglages › SOS en cas de chute</b>.", "Écris <b>ton nom</b> et <b>ton numéro</b> (pour que le destinataire puisse te rappeler) et jusqu'à <b>3 numéros à prévenir</b>.", "Accorde l'autorisation <b>SMS</b> quand Android la demande : elle sert seulement à envoyer l'alerte.", "Choisis la <b>sensibilité</b> (basse, moyenne, haute) et active.", "Appuie sur <b>Tester le SOS</b> : un message d'ESSAI est envoyé à tes numéros, clairement indiqué comme test.", "Dès lors, si tu dépasses 25 km/h, qu'il y a un choc fort puis que tu restes immobile, un compte à rebours de 30 secondes avec sirène démarre : touche <b>Ça va</b> pour annuler."],
   ["Öffne <b>Menü › Einstellungen › Sturz-SOS</b>.", "Trage <b>deinen Namen</b> und <b>deine Nummer</b> ein (damit der Empfänger dich zurückrufen kann) und bis zu <b>3 Nummern zum Benachrichtigen</b>.", "Erteile die <b>SMS</b>-Berechtigung, wenn Android fragt: Sie dient nur dem Senden der Warnung.", "Wähle die <b>Empfindlichkeit</b> (niedrig, mittel, hoch) und schalte ein.", "Drücke <b>SOS testen</b>: Eine TEST-Nachricht, klar als Test gekennzeichnet, geht an deine Nummern.", "Ab jetzt startet bei über 25 km/h, hartem Aufprall und anschließendem Stillstand ein 30-Sekunden-Countdown mit Sirene: Tippe <b>Mir geht's gut</b> zum Abbrechen."],
   ["Abre <b>Menú › Ajustes › SOS por caída</b>.", "Escribe <b>tu nombre</b> y <b>tu número</b> (para que quien reciba el SMS pueda llamarte) y hasta <b>3 números a avisar</b>.", "Concede el permiso de <b>SMS</b> cuando Android lo pida: solo sirve para enviar el aviso.", "Elige la <b>sensibilidad</b> (baja, media, alta) y actívalo.", "Pulsa <b>Probar SOS</b>: envía un mensaje de PRUEBA a tus números, claramente marcado como prueba.", "Desde ahora, si vas a más de 25 km/h, hay un golpe fuerte y luego te quedas quieto, empieza una cuenta atrás de 30 segundos con sirena: toca <b>Estoy bien</b> para cancelar."])),
 ('viaggio', T('Far seguire il viaggio a casa', 'Letting home follow your trip', 'Faire suivre ton trajet à la maison', 'Zuhause die Fahrt verfolgen lassen', 'Dejar que en casa sigan tu viaje'), T(
   ["Avvia la navigazione verso la tua destinazione.", "Apri <b>Menu › Segui il mio viaggio</b>.", "Scegli la durata: <b>2, 6, 12 o 24 ore</b>.", "Si apre il foglio Condividi: manda il link su WhatsApp, SMS o dove vuoi.", "Chi lo riceve vede la tua posizione su una mappa, senza installare niente e senza account.", "Per smettere: <b>Menu › Smetti di condividere il viaggio</b>. Il link si chiude da solo alla scadenza e quando termini la navigazione."],
   ["Start navigating to your destination.", "Open <b>Menu › Follow my trip</b>.", "Choose the duration: <b>2, 6, 12 or 24 hours</b>.", "The Share sheet opens: send the link on WhatsApp, SMS or anywhere you like.", "Whoever receives it sees your position on a map, with nothing to install and no account.", "To stop: <b>Menu › Stop sharing the trip</b>. The link closes by itself when it expires and when you end navigation."],
   ["Lance la navigation vers ta destination.", "Ouvre <b>Menu › Suivre mon trajet</b>.", "Choisis la durée : <b>2, 6, 12 ou 24 heures</b>.", "La feuille de partage s'ouvre : envoie le lien par WhatsApp, SMS ou où tu veux.", "Le destinataire voit ta position sur une carte, sans rien installer et sans compte.", "Pour arrêter : <b>Menu › Arrêter de partager le trajet</b>. Le lien se ferme tout seul à l'expiration et quand tu termines la navigation."],
   ["Starte die Navigation zu deinem Ziel.", "Öffne <b>Menü › Meine Fahrt verfolgen</b>.", "Wähle die Dauer: <b>2, 6, 12 oder 24 Stunden</b>.", "Das Teilen-Fenster öffnet sich: Sende den Link per WhatsApp, SMS oder wohin du willst.", "Der Empfänger sieht deine Position auf einer Karte, ohne Installation und ohne Konto.", "Zum Beenden: <b>Menü › Fahrt nicht mehr teilen</b>. Der Link endet von selbst bei Ablauf und mit der Navigation."],
   ["Inicia la navegación hacia tu destino.", "Abre <b>Menú › Seguir mi viaje</b>.", "Elige la duración: <b>2, 6, 12 o 24 horas</b>.", "Se abre la hoja de compartir: envía el enlace por WhatsApp, SMS o donde quieras.", "Quien lo recibe ve tu posición en un mapa, sin instalar nada y sin cuenta.", "Para dejar de hacerlo: <b>Menú › Dejar de compartir el viaje</b>. El enlace se cierra solo al caducar y al terminar la navegación."])),
 ('mancato', T("Allarme di mancato arrivo", 'Missed-arrival alarm', "Alarme d'arrivée manquée", 'Alarm bei Nichtankunft', 'Alarma de llegada'), T(
   ["Imposta prima i numeri dell'SOS (vedi la guida sopra): l'allarme usa gli stessi.", "Apri <b>Menu › Impostazioni › Funzioni in sella</b> e accendi <b>Allarme di mancato arrivo</b>.", "Scegli la <b>tolleranza</b>: 15, 30, 60 o 90 minuti dopo l'ora prevista.", "Avvia la navigazione: l'app ti conferma che l'allarme è attivo.", "Se non arrivi entro l'orario previsto più la tolleranza, i tuoi contatti ricevono un SMS con l'<b>ultima posizione</b> (e il link del viaggio, se lo condividi).", "Quando termini tu la navigazione o arrivi a destinazione, l'allarme si annulla."],
   ["First set the SOS numbers (see the guide above): the alarm uses the same ones.", "Open <b>Menu › Settings › Riding features</b> and switch on <b>Missed-arrival alarm</b>.", "Choose the <b>tolerance</b>: 15, 30, 60 or 90 minutes after the expected time.", "Start navigating: the app confirms the alarm is on.", "If you do not arrive by the expected time plus the tolerance, your contacts receive an SMS with your <b>last position</b> (and the trip link, if you share it).", "When you end navigation or reach the destination, the alarm is cancelled."],
   ["Règle d'abord les numéros du SOS (voir le guide ci-dessus) : l'alarme utilise les mêmes.", "Ouvre <b>Menu › Réglages › Fonctions en selle</b> et active <b>Alarme d'arrivée manquée</b>.", "Choisis la <b>tolérance</b> : 15, 30, 60 ou 90 minutes après l'heure prévue.", "Lance la navigation : l'appli confirme que l'alarme est active.", "Si tu n'arrives pas à l'heure prévue plus la tolérance, tes contacts reçoivent un SMS avec ta <b>dernière position</b> (et le lien du trajet, si tu le partages).", "Quand tu termines la navigation ou arrives à destination, l'alarme est annulée."],
   ["Richte zuerst die SOS-Nummern ein (siehe Anleitung oben): Der Alarm nutzt dieselben.", "Öffne <b>Menü › Einstellungen › Funktionen unterwegs</b> und schalte <b>Alarm bei Nichtankunft</b> ein.", "Wähle die <b>Toleranz</b>: 15, 30, 60 oder 90 Minuten nach der geplanten Zeit.", "Starte die Navigation: Die App bestätigt, dass der Alarm aktiv ist.", "Kommst du nicht bis zur geplanten Zeit plus Toleranz an, erhalten deine Kontakte eine SMS mit deiner <b>letzten Position</b> (und dem Fahrtlink, falls geteilt).", "Beendest du die Navigation oder erreichst das Ziel, wird der Alarm abgebrochen."],
   ["Configura antes los números del SOS (mira la guía de arriba): la alarma usa los mismos.", "Abre <b>Menú › Ajustes › Funciones en ruta</b> y activa <b>Alarma de llegada</b>.", "Elige la <b>tolerancia</b>: 15, 30, 60 o 90 minutos tras la hora prevista.", "Inicia la navegación: la app confirma que la alarma está activa.", "Si no llegas a la hora prevista más la tolerancia, tus contactos reciben un SMS con tu <b>última posición</b> (y el enlace del viaje, si lo compartes).", "Cuando termines la navegación o llegues al destino, la alarma se cancela."])),
 ('gruppo', T('Organizzare un giro di gruppo', 'Setting up a group ride', 'Organiser une sortie de groupe', 'Eine Gruppenfahrt organisieren', 'Organizar una ruta en grupo'), T(
   ["Apri <b>Menu › Giro di gruppo</b> e tocca <b>Crea un gruppo</b>.", "Dai un nome al giro (facoltativo) e scegli la durata: 6, 12 o 24 ore.", "Compare un <b>QR</b>: chi è con te lo inquadra con la fotocamera. Per gli altri tocca <b>Condividi il link</b>.", "Chi tocca il link si apre in IDQ Biker Maps e tocca <b>Entra</b>: gli altri vedranno il suo nome (scritto in Impostazioni › SOS).", "Mentre navigate vi vedete sulla mappa e l'app ti avvisa se qualcuno è a più di 3 km da te.", "Chi non ha l'app apre lo stesso link e vede il gruppo su una pagina web. Per uscire: <b>Menu › Giro di gruppo › Esci dal gruppo</b>."],
   ["Open <b>Menu › Group ride</b> and tap <b>Create a group</b>.", "Name the ride (optional) and choose the duration: 6, 12 or 24 hours.", "A <b>QR</b> appears: whoever is with you scans it with the camera. For the others tap <b>Share the link</b>.", "Whoever taps the link opens IDQ Biker Maps and taps <b>Join</b>: the others will see their name (written in Settings › SOS).", "While you navigate you see each other on the map and the app warns you if someone is more than 3 km from you.", "Those without the app open the same link and see the group on a web page. To leave: <b>Menu › Group ride › Leave the group</b>."],
   ["Ouvre <b>Menu › Sortie de groupe</b> et touche <b>Créer un groupe</b>.", "Donne un nom à la sortie (facultatif) et choisis la durée : 6, 12 ou 24 heures.", "Un <b>QR</b> apparaît : ceux qui sont avec toi le scannent avec l'appareil photo. Pour les autres touche <b>Partager le lien</b>.", "Celui qui touche le lien ouvre IDQ Biker Maps et touche <b>Rejoindre</b> : les autres verront son nom (écrit dans Réglages › SOS).", "Pendant la navigation vous vous voyez sur la carte et l'appli t'avertit si quelqu'un est à plus de 3 km de toi.", "Ceux qui n'ont pas l'appli ouvrent le même lien et voient le groupe sur une page web. Pour quitter : <b>Menu › Sortie de groupe › Quitter le groupe</b>."],
   ["Öffne <b>Menü › Gruppenfahrt</b> und tippe auf <b>Gruppe erstellen</b>.", "Gib der Fahrt einen Namen (optional) und wähle die Dauer: 6, 12 oder 24 Stunden.", "Ein <b>QR-Code</b> erscheint: Wer bei dir ist, scannt ihn mit der Kamera. Für die anderen tippe auf <b>Link teilen</b>.", "Wer den Link antippt, öffnet IDQ Biker Maps und tippt auf <b>Beitreten</b>: Die anderen sehen seinen Namen (eingetragen in Einstellungen › SOS).", "Während der Navigation seht ihr euch auf der Karte, und die App warnt dich, wenn jemand mehr als 3 km entfernt ist.", "Wer die App nicht hat, öffnet denselben Link und sieht die Gruppe auf einer Webseite. Zum Verlassen: <b>Menü › Gruppenfahrt › Gruppe verlassen</b>."],
   ["Abre <b>Menú › Ruta en grupo</b> y toca <b>Crear un grupo</b>.", "Pon nombre a la ruta (opcional) y elige la duración: 6, 12 o 24 horas.", "Aparece un <b>QR</b>: quien está contigo lo escanea con la cámara. Para los demás toca <b>Compartir el enlace</b>.", "Quien toca el enlace abre IDQ Biker Maps y toca <b>Entrar</b>: los demás verán su nombre (escrito en Ajustes › SOS).", "Mientras navegáis os veis en el mapa y la app te avisa si alguien está a más de 3 km de ti.", "Quien no tiene la app abre el mismo enlace y ve el grupo en una página web. Para salir: <b>Menú › Ruta en grupo › Salir del grupo</b>."])),
 ('casco', T("Usare i tasti dell'interfono del casco", 'Using the helmet intercom buttons', "Utiliser les boutons de l'interphone du casque", 'Die Tasten der Helm-Gegensprechanlage nutzen', 'Usar los botones del intercomunicador del casco'), T(
   ["Collega l'interfono (Sena, Cardo o simili) al telefono via Bluetooth come al solito.", "Apri <b>Menu › Impostazioni › Funzioni in sella</b> e controlla che <b>Comandi dal casco</b> e <b>Controllo audio nel casco</b> siano accesi (lo sono di base).", "Avvia la navigazione: a inizio giro l'app ti dice se il casco è collegato e se il volume è troppo basso.", "<b>Play/pausa</b> ripete l'ultima indicazione, <b>avanti</b> dice quanti chilometri e minuti mancano, <b>indietro</b> accende o spegne la voce.", "Se il tuo interfono usa tasti diversi, i comandi multimediali standard di Android funzionano allo stesso modo."],
   ["Connect the intercom (Sena, Cardo or similar) to the phone over Bluetooth as usual.", "Open <b>Menu › Settings › Riding features</b> and check that <b>Helmet controls</b> and <b>Helmet audio check</b> are on (they are by default).", "Start navigating: at the start of the ride the app tells you whether the helmet is connected and whether the volume is too low.", "<b>Play/pause</b> repeats the last instruction, <b>next</b> says how many kilometres and minutes are left, <b>previous</b> turns the voice on or off.", "If your intercom uses different buttons, the standard Android media commands work the same way."],
   ["Connecte l'interphone (Sena, Cardo ou similaire) au téléphone en Bluetooth comme d'habitude.", "Ouvre <b>Menu › Réglages › Fonctions en selle</b> et vérifie que <b>Commandes du casque</b> et <b>Contrôle audio dans le casque</b> sont actifs (c'est le cas par défaut).", "Lance la navigation : au départ l'appli te dit si le casque est connecté et si le volume est trop bas.", "<b>Lecture/pause</b> répète la dernière indication, <b>suivant</b> dit combien de kilomètres et de minutes il reste, <b>précédent</b> active ou coupe la voix.", "Si ton interphone utilise d'autres boutons, les commandes multimédia standard d'Android fonctionnent pareil."],
   ["Verbinde die Gegensprechanlage (Sena, Cardo o. ä.) wie gewohnt per Bluetooth mit dem Telefon.", "Öffne <b>Menü › Einstellungen › Funktionen unterwegs</b> und prüfe, dass <b>Helmsteuerung</b> und <b>Audio-Check im Helm</b> an sind (standardmäßig der Fall).", "Starte die Navigation: Zu Beginn sagt die App, ob der Helm verbunden ist und ob die Lautstärke zu niedrig ist.", "<b>Play/Pause</b> wiederholt die letzte Ansage, <b>Weiter</b> nennt die Restkilometer und -minuten, <b>Zurück</b> schaltet die Stimme ein oder aus.", "Nutzt deine Anlage andere Tasten, funktionieren die Standard-Medientasten von Android genauso."],
   ["Conecta el intercomunicador (Sena, Cardo o similar) al teléfono por Bluetooth como siempre.", "Abre <b>Menú › Ajustes › Funciones en ruta</b> y comprueba que <b>Controles del casco</b> y <b>Control de audio en el casco</b> están activados (lo están por defecto).", "Inicia la navegación: al empezar la app te dice si el casco está conectado y si el volumen es demasiado bajo.", "<b>Play/pausa</b> repite la última indicación, <b>siguiente</b> dice cuántos kilómetros y minutos faltan, <b>anterior</b> activa o apaga la voz.", "Si tu intercomunicador usa otros botones, los comandos multimedia estándar de Android funcionan igual."])),
 ('giri', T('Trovare un giro con «Dove vado oggi?»', 'Finding a ride with “Where do I ride today?”', 'Trouver une boucle avec « Où rouler aujourd\'hui ? »', 'Eine Tour finden mit „Wohin fahre ich heute?“', 'Encontrar una ruta con «¿Adónde voy hoy?»'), T(
   ["Aspetta che il GPS ti trovi e apri <b>Menu › Dove vado oggi?</b>.", "Scegli <b>quanto vuoi guidare</b> (da 1 a 6 ore) e <b>che strade</b> preferisci: normali, curvose o molto curvose. Per lo sterrato spunta <b>Modalità avventura</b>.", "Tocca <b>Cerca giri</b>: in pochi secondi ottieni fino a 4 giri ad anello, dal più curvoso, con km, durata e un giudizio (veloce, scorrevole, curvoso, molto curvoso).", "Scegline uno: l'app calcola il percorso e lo navighi come sempre, con indicazioni, limiti e avvisi.", "Per vedere dove sono le strade più belle prima di partire accendi <b>Menu › Mappa delle curve</b> e avvicina la mappa.", "Con una destinazione già scelta, <b>Menu › Percorso › Percorso panoramico</b> sceglie le strade curvose invece delle più veloci."],
   ["Wait for the GPS to find you and open <b>Menu › Where do I ride today?</b>.", "Choose <b>how long you want to ride</b> (1 to 6 hours) and <b>which roads</b> you prefer: normal, twisty or very twisty. For unpaved roads tick <b>Adventure mode</b>.", "Tap <b>Find rides</b>: within seconds you get up to 4 loop rides, twistiest first, with km, time and a verdict (fast, flowing, twisty, very twisty).", "Pick one: the app calculates the route and you navigate it as usual, with directions, limits and alerts.", "To see where the best roads are before leaving, switch on <b>Menu › Bend map</b> and zoom in.", "With a destination already chosen, <b>Menu › Route › Scenic route</b> picks twisty roads instead of the fastest ones."],
   ["Attends que le GPS te localise et ouvre <b>Menu › Où rouler aujourd'hui ?</b>.", "Choisis <b>combien de temps tu veux rouler</b> (de 1 à 6 heures) et <b>quelles routes</b> tu préfères : normales, sinueuses ou très sinueuses. Pour les chemins, coche <b>Mode aventure</b>.", "Touche <b>Chercher des boucles</b> : en quelques secondes tu obtiens jusqu'à 4 boucles, la plus sinueuse d'abord, avec km, durée et un verdict (rapide, roulant, sinueux, très sinueux).", "Choisis-en une : l'appli calcule l'itinéraire et tu le suis comme d'habitude, avec indications, limites et alertes.", "Pour voir où sont les plus belles routes avant de partir, active <b>Menu › Carte des virages</b> et rapproche la carte.", "Avec une destination déjà choisie, <b>Menu › Itinéraire › Itinéraire panoramique</b> choisit les routes sinueuses plutôt que les plus rapides."],
   ["Warte, bis das GPS dich gefunden hat, und öffne <b>Menü › Wohin fahre ich heute?</b>.", "Wähle, <b>wie lange du fahren willst</b> (1 bis 6 Stunden) und <b>welche Straßen</b> du bevorzugst: normale, kurvige oder sehr kurvige. Für Schotter hake <b>Abenteuermodus</b> an.", "Tippe auf <b>Touren suchen</b>: In wenigen Sekunden erhältst du bis zu 4 Rundtouren, die kurvigste zuerst, mit km, Dauer und Urteil (schnell, flüssig, kurvig, sehr kurvig).", "Wähle eine aus: Die App berechnet die Route, und du navigierst wie gewohnt, mit Ansagen, Limits und Warnungen.", "Um vor der Abfahrt zu sehen, wo die schönsten Straßen sind, schalte <b>Menü › Kurvenkarte</b> ein und zoome heran.", "Ist schon ein Ziel gewählt, wählt <b>Menü › Route › Panoramaroute</b> kurvige statt der schnellsten Straßen."],
   ["Espera a que el GPS te localice y abre <b>Menú › ¿Adónde voy hoy?</b>.", "Elige <b>cuánto quieres rodar</b> (de 1 a 6 horas) y <b>qué carreteras</b> prefieres: normales, reviradas o muy reviradas. Para la tierra marca <b>Modo aventura</b>.", "Toca <b>Buscar rutas</b>: en pocos segundos obtienes hasta 4 rutas circulares, la más revirada primero, con km, duración y un veredicto (rápido, fluido, revirado, muy revirado).", "Elige una: la app calcula la ruta y la navegas como siempre, con indicaciones, límites y avisos.", "Para ver dónde están las mejores carreteras antes de salir, activa <b>Menú › Mapa de curvas</b> y acerca el mapa.", "Con un destino ya elegido, <b>Menú › Ruta › Ruta panorámica</b> elige carreteras reviradas en vez de las más rápidas."])),
 ('moto', T('Impostare garage, autonomia e manutenzione', 'Setting up garage, range and maintenance', "Régler garage, autonomie et entretien", 'Garage, Reichweite und Wartung einrichten', 'Configurar garaje, autonomía y mantenimiento'), T(
   ["Apri <b>Menu › Impostazioni › Garage e rifornimenti</b> e tocca <b>Aggiungi una moto</b>.", "Scrivi nome, serbatoio, autonomia col pieno e i chilometri del contachilometri.", "Dopo ogni pieno tocca <b>Menu › Ho fatto il pieno</b> e scrivi litri e costo: con due pieni l'app calcola il <b>consumo reale</b> e il <b>costo al chilometro</b>.", "In <b>Scadenze di manutenzione</b> aggiungi tagliando, catena, gomme... con ogni quanti km: a inizio giro l'app ti avvisa quando mancano meno di 300 km.", "Con un percorso attivo, <b>Menu › Distributore più conveniente</b> elenca i distributori del tragitto per prezzo e deviazione: tocca per aggiungerlo come tappa.", "Più moto? Tocca <b>Usa questa moto</b> per cambiare quella attiva: ognuna ha i suoi chilometri."],
   ["Open <b>Menu › Settings › Garage and refuelling</b> and tap <b>Add a motorcycle</b>.", "Enter name, tank, range on a full tank and the odometer kilometres.", "After each fill-up tap <b>Menu › I filled the tank</b> and enter litres and cost: with two fill-ups the app works out <b>real consumption</b> and <b>cost per kilometre</b>.", "In <b>Maintenance deadlines</b> add service, chain, tyres... with the km interval: at the start of a ride the app warns you when fewer than 300 km remain.", "With an active route, <b>Menu › Cheapest petrol station</b> lists the stations along the way by price and detour: tap to add one as a stop.", "Several bikes? Tap <b>Use this motorcycle</b> to change the active one: each has its own kilometres."],
   ["Ouvre <b>Menu › Réglages › Garage et ravitaillements</b> et touche <b>Ajouter une moto</b>.", "Saisis nom, réservoir, autonomie avec le plein et kilomètres du compteur.", "Après chaque plein touche <b>Menu › J'ai fait le plein</b> et saisis litres et coût : avec deux pleins l'appli calcule la <b>consommation réelle</b> et le <b>coût au kilomètre</b>.", "Dans <b>Échéances d'entretien</b> ajoute révision, chaîne, pneus... avec l'intervalle en km : au départ l'appli t'avertit quand il reste moins de 300 km.", "Avec un itinéraire actif, <b>Menu › Station-service la plus avantageuse</b> liste les stations du trajet par prix et détour : touche pour l'ajouter comme étape.", "Plusieurs motos ? Touche <b>Utiliser cette moto</b> pour changer l'active : chacune a ses kilomètres."],
   ["Öffne <b>Menü › Einstellungen › Garage und Tanken</b> und tippe auf <b>Motorrad hinzufügen</b>.", "Gib Name, Tank, Reichweite bei vollem Tank und Tachostand ein.", "Tippe nach jedem Tanken auf <b>Menü › Ich habe vollgetankt</b> und trage Liter und Kosten ein: Ab zwei Tankfüllungen berechnet die App <b>realen Verbrauch</b> und <b>Kosten pro Kilometer</b>.", "Unter <b>Wartungstermine</b> trägst du Inspektion, Kette, Reifen... mit Intervall in km ein: Zu Fahrtbeginn warnt dich die App, wenn weniger als 300 km bleiben.", "Bei aktiver Route listet <b>Menü › Günstigste Tankstelle</b> die Tankstellen der Strecke nach Preis und Umweg: Tippe, um eine als Zwischenziel hinzuzufügen.", "Mehrere Motorräder? Tippe auf <b>Dieses Motorrad verwenden</b>, um das aktive zu wechseln: Jedes hat seine eigenen Kilometer."],
   ["Abre <b>Menú › Ajustes › Garaje y repostajes</b> y toca <b>Añadir una moto</b>.", "Escribe nombre, depósito, autonomía con el depósito lleno y los kilómetros del cuentakilómetros.", "Tras cada repostaje toca <b>Menú › He llenado el depósito</b> y escribe litros y coste: con dos repostajes la app calcula el <b>consumo real</b> y el <b>coste por kilómetro</b>.", "En <b>Vencimientos de mantenimiento</b> añade revisión, cadena, neumáticos... con el intervalo en km: al empezar la ruta la app te avisa cuando faltan menos de 300 km.", "Con una ruta activa, <b>Menú › Gasolinera más económica</b> lista las gasolineras del trayecto por precio y desvío: toca para añadirla como parada.", "¿Varias motos? Toca <b>Usar esta moto</b> para cambiar la activa: cada una tiene sus kilómetros."])),
 ('mappe', T('Scaricare le mappe offline', 'Downloading offline maps', 'Télécharger les cartes hors ligne', 'Offline-Karten laden', 'Descargar mapas sin conexión'), T(
   ["Collegati al Wi-Fi e tieni il telefono in carica.", "Al primo avvio l'app propone di scaricare l'Italia: tocca <b>Scarica</b> e aspetta la fine (compare una finestra con l'avanzamento).", "Puoi farlo anche dopo da <b>Menu › Mappe offline › Gestisci le mappe</b>.", "Lascia attivo <b>Aggiorna da sole (Wi-Fi e in carica)</b>: le mappe si aggiornano da sole ogni mese.", "Con la rete l'app usa le mappe online; senza rete passa da sola a quelle scaricate: gallerie e montagne non sono più un problema."],
   ["Connect to Wi-Fi and keep the phone charging.", "At first launch the app offers to download Italy: tap <b>Download</b> and wait for the end (a window shows the progress).", "You can also do it later from <b>Menu › Offline maps › Manage maps</b>.", "Leave <b>Update by themselves (Wi-Fi and charging)</b> on: the maps update on their own every month.", "With a connection the app uses online maps; without one it switches by itself to the downloaded ones: tunnels and mountains are no longer a problem."],
   ["Connecte-toi au Wi-Fi et laisse le téléphone en charge.", "Au premier lancement l'appli propose de télécharger l'Italie : touche <b>Télécharger</b> et attends la fin (une fenêtre montre l'avancement).", "Tu peux aussi le faire plus tard depuis <b>Menu › Cartes hors ligne › Gérer les cartes</b>.", "Laisse activé <b>Mettre à jour seules (Wi-Fi et en charge)</b> : les cartes se mettent à jour toutes seules chaque mois.", "Avec du réseau l'appli utilise les cartes en ligne ; sans réseau elle passe toute seule aux cartes téléchargées : tunnels et montagnes ne sont plus un problème."],
   ["Verbinde dich mit WLAN und lass das Telefon laden.", "Beim ersten Start bietet die App den Download von Italien an: Tippe auf <b>Herunterladen</b> und warte bis zum Ende (ein Fenster zeigt den Fortschritt).", "Du kannst es auch später unter <b>Menü › Offline-Karten › Karten verwalten</b> tun.", "Lass <b>Von selbst aktualisieren (WLAN und Laden)</b> an: Die Karten aktualisieren sich jeden Monat von allein.", "Mit Netz nutzt die App Online-Karten; ohne Netz wechselt sie von selbst zu den geladenen: Tunnel und Berge sind kein Problem mehr."],
   ["Conéctate al Wi-Fi y deja el teléfono cargando.", "En el primer arranque la app ofrece descargar Italia: toca <b>Descargar</b> y espera al final (una ventana muestra el avance).", "También puedes hacerlo luego desde <b>Menú › Mapas sin conexión › Gestionar los mapas</b>.", "Deja activado <b>Actualizar solos (Wi-Fi y cargando)</b>: los mapas se actualizan solos cada mes.", "Con cobertura la app usa mapas online; sin ella pasa sola a los descargados: túneles y montañas ya no son un problema."])),
]

FAQ_H = T('Domande frequenti', 'Frequently asked questions', 'Questions fréquentes', 'Häufige Fragen', 'Preguntas frecuentes')
FAQ = [
 (T('Funziona senza internet?', 'Does it work without internet?', 'Fonctionne-t-elle sans internet ?', 'Funktioniert es ohne Internet?', '¿Funciona sin internet?'),
  T("Sì per mappa, percorsi e voce, con le mappe scaricate. Servono internet il meteo, \"Dove vado oggi?\", la mappa delle curve, il profilo altimetrico, \"Segui il mio viaggio\" e il giro di gruppo.", "Yes for map, routes and voice, with the downloaded maps. Weather, \"Where do I ride today?\", the bend map, the elevation profile, \"Follow my trip\" and group rides need internet.", "Oui pour la carte, les itinéraires et la voix, avec les cartes téléchargées. La météo, « Où rouler aujourd'hui ? », la carte des virages, le profil d'altitude, « Suivre mon trajet » et la sortie de groupe demandent internet.", "Ja für Karte, Routen und Stimme, mit geladenen Karten. Wetter, „Wohin fahre ich heute?“, Kurvenkarte, Höhenprofil, „Meine Fahrt verfolgen“ und Gruppenfahrt brauchen Internet.", "Sí para mapa, rutas y voz, con los mapas descargados. El tiempo, «¿Adónde voy hoy?», el mapa de curvas, el perfil de altitud, «Seguir mi viaje» y la ruta en grupo necesitan internet.")),
 (T('Quanto costa e ci sono abbonamenti?', 'How much does it cost and are there subscriptions?', 'Combien ça coûte et y a-t-il des abonnements ?', 'Was kostet es, und gibt es Abos?', '¿Cuánto cuesta y hay suscripciones?'),
  T("Si scarica gratis e ha 15 giorni di prova con tutte le funzioni. Poi si sblocca con un acquisto unico su Google Play: nessun abbonamento, nessuna pubblicità. Il prezzo lo vedi su Google Play. I dati di mappe, meteo e quote sono fonti libere: nessun costo nascosto.", "It is free to download and has 15 days of trial with every feature. Then it unlocks with a single purchase on Google Play: no subscription, no ads. You see the price on Google Play. Map, weather and elevation data are open sources: no hidden costs.", "Elle se télécharge gratuitement et a 15 jours d'essai avec toutes les fonctions. Ensuite elle se débloque avec un achat unique sur Google Play : pas d'abonnement, pas de publicité. Tu vois le prix sur Google Play. Les données de cartes, météo et altitude viennent de sources libres : aucun coût caché.", "Sie lässt sich kostenlos laden und hat 15 Tage Testphase mit allen Funktionen. Danach schaltet man sie mit einem Einmalkauf bei Google Play frei: kein Abo, keine Werbung. Den Preis siehst du bei Google Play. Karten-, Wetter- und Höhendaten stammen aus freien Quellen: keine versteckten Kosten.", "Se descarga gratis y tiene 15 días de prueba con todas las funciones. Luego se desbloquea con una compra única en Google Play: sin suscripción, sin publicidad. El precio lo ves en Google Play. Los datos de mapas, tiempo y altitud proceden de fuentes libres: sin costes ocultos.")),
 (T('Posso sbloccarla subito, senza aspettare i 15 giorni?', 'Can I unlock it right away, without waiting 15 days?', 'Puis-je la débloquer tout de suite, sans attendre 15 jours ?', 'Kann ich sie sofort freischalten, ohne 15 Tage zu warten?', '¿Puedo desbloquearla ya, sin esperar 15 días?'),
  T("Sì. Dall'avviso iniziale (\"Sblocca ora\") o da Menu › Informazioni puoi pagare subito: i giorni di prova che restano non servono più.", "Yes. From the first message (\"Unlock now\") or from Menu › Information you can pay right away: the remaining trial days are no longer needed.", "Oui. Depuis le message de départ (« Débloquer maintenant ») ou depuis Menu › Informations tu peux payer tout de suite : les jours d'essai restants ne servent plus.", "Ja. Über die erste Meldung („Jetzt freischalten“) oder Menü › Informationen kannst du sofort zahlen: Die restlichen Testtage werden nicht mehr gebraucht.", "Sí. Desde el aviso inicial («Desbloquear ahora») o desde Menú › Información puedes pagar ya: los días de prueba que quedan ya no hacen falta.")),
 (T('Se la disinstallo e la reinstallo ricomincia la prova?', 'If I uninstall and reinstall, does the trial start again?', 'Si je la désinstalle et la réinstalle, l\'essai recommence-t-il ?', 'Startet die Testphase neu, wenn ich deinstalliere und neu installiere?', 'Si la desinstalo y la reinstalo, ¿empieza otra vez la prueba?'),
  T("No: la prova continua dal punto in cui era, perché il nostro server ricorda la data di primo avvio con un codice anonimo del telefono. Se hai già pagato, \"Ho già acquistato l'app\" ti sblocca senza pagare di nuovo.", "No: the trial continues from where it was, because our server remembers the first-launch date with an anonymous phone code. If you have already paid, \"I already bought the app\" unlocks you without paying again.", "Non : l'essai continue là où il était, car notre serveur retient la date de premier lancement avec un code anonyme du téléphone. Si tu as déjà payé, « J'ai déjà acheté l'appli » te débloque sans payer de nouveau.", "Nein: Die Testphase läuft dort weiter, wo sie war, weil unser Server das Datum des ersten Starts mit einem anonymen Telefoncode speichert. Hast du schon bezahlt, schaltet „Ich habe die App schon gekauft“ ohne erneute Zahlung frei.", "No: la prueba continúa por donde iba, porque nuestro servidor recuerda la fecha del primer arranque con un código anónimo del teléfono. Si ya has pagado, «Ya he comprado la app» te desbloquea sin pagar de nuevo.")),
 (T('Dove funziona?', 'Where does it work?', 'Où fonctionne-t-elle ?', 'Wo funktioniert es?', '¿Dónde funciona?'),
  T("Le mappe offline sono quelle dell'Italia. Meteo, giri, curve e quote sono per l'Italia; la mappa online e i percorsi funzionano anche nei paesi vicini quando hai la rete.", "Offline maps cover Italy. Weather, rides, bends and elevations are for Italy; the online map and routes also work in neighbouring countries when you have a connection.", "Les cartes hors ligne couvrent l'Italie. Météo, boucles, virages et altitudes concernent l'Italie ; la carte en ligne et les itinéraires fonctionnent aussi dans les pays voisins avec du réseau.", "Die Offline-Karten decken Italien ab. Wetter, Touren, Kurven und Höhen gelten für Italien; die Online-Karte und Routen funktionieren mit Netz auch in Nachbarländern.", "Los mapas sin conexión cubren Italia. Tiempo, rutas, curvas y altitudes son para Italia; el mapa online y las rutas también funcionan en países vecinos cuando tienes cobertura.")),
 (T('Cosa succede ai miei dati?', 'What happens to my data?', 'Que deviennent mes données ?', 'Was passiert mit meinen Daten?', '¿Qué pasa con mis datos?'),
  T("Niente account, niente pubblicità, niente analisi. Contatti, SOS, garage e scatola nera restano sul telefono. Solo se usi \"Segui il mio viaggio\", il giro di gruppo o il meteo, alcuni dati vanno al nostro server per il tempo necessario e poi si cancellano. Leggi l'informativa completa.", "No account, no ads, no analytics. Contacts, SOS, garage and black box stay on your phone. Only if you use \"Follow my trip\", group rides or weather, some data goes to our server for as long as needed and is then deleted. Read the full privacy policy.", "Pas de compte, pas de publicité, pas d'analyse. Contacts, SOS, garage et boîte noire restent sur le téléphone. Seulement si tu utilises « Suivre mon trajet », la sortie de groupe ou la météo, certaines données vont à notre serveur le temps nécessaire puis sont effacées. Lis la politique de confidentialité complète.", "Kein Konto, keine Werbung, keine Analyse. Kontakte, SOS, Garage und Blackbox bleiben auf dem Telefon. Nur wenn du „Meine Fahrt verfolgen“, die Gruppenfahrt oder das Wetter nutzt, gehen einige Daten so lange wie nötig an unseren Server und werden dann gelöscht. Lies die vollständige Datenschutzerklärung.", "Sin cuenta, sin publicidad, sin análisis. Contactos, SOS, garaje y caja negra quedan en el teléfono. Solo si usas «Seguir mi viaje», la ruta en grupo o el tiempo, algunos datos van a nuestro servidor el tiempo necesario y luego se borran. Lee la política de privacidad completa.")),
 (T("L'SOS sostituisce il 112?", 'Does the SOS replace 112?', 'Le SOS remplace-t-il le 112 ?', 'Ersetzt der SOS den Notruf 112?', '¿El SOS sustituye al 112?'),
  T("No. È un aiuto in più: manda un SMS ai tuoi contatti, che devono chiamare il 112. Funziona solo con segnale telefonico e non può rilevare ogni caduta. Casco, protezioni e prudenza restano la tua prima sicurezza.", "No. It is an extra help: it texts your contacts, who must call 112. It works only with phone signal and cannot detect every fall. Helmet, protective gear and prudence remain your first safety.", "Non. C'est une aide en plus : il envoie un SMS à tes contacts, qui doivent appeler le 112. Il ne fonctionne qu'avec du réseau et ne peut pas détecter toutes les chutes. Casque, protections et prudence restent ta première sécurité.", "Nein. Er ist eine zusätzliche Hilfe: Er schickt deinen Kontakten eine SMS, die den Notruf 112 wählen müssen. Er funktioniert nur mit Mobilfunkempfang und erkennt nicht jeden Sturz. Helm, Schutzkleidung und Vorsicht bleiben deine erste Sicherheit.", "No. Es una ayuda extra: envía un SMS a tus contactos, que deben llamar al 112. Solo funciona con cobertura y no puede detectar todas las caídas. Casco, protecciones y prudencia siguen siendo tu primera seguridad.")),
 (T('Posso usarla con il Galaxy Watch?', 'Can I use it with a smartwatch?', 'Puis-je l\'utiliser avec une montre connectée ?', 'Kann ich es mit einer Smartwatch nutzen?', '¿Puedo usarla con un reloj inteligente?'),
  T("Per ora le indicazioni sull'orologio sono nell'app IDQ Navigator; una versione per Biker Maps arriverà dopo.", "For now watch directions are in the IDQ Navigator app; a version for Biker Maps will follow.", "Pour l'instant les indications sur la montre sont dans l'appli IDQ Navigator ; une version pour Biker Maps suivra.", "Derzeit gibt es Ansagen auf der Uhr in der App IDQ Navigator; eine Version für Biker Maps folgt.", "Por ahora las indicaciones en el reloj están en la app IDQ Navigator; una versión para Biker Maps llegará después.")),
]
WARN = T("Sono stime e aiuti: non sostituiscono la tua attenzione. Controlla sempre le condizioni reali della strada e del meteo, rispetta il Codice della Strada e non usare il telefono mentre guidi.", "These are estimates and aids: they do not replace your attention. Always check the real road and weather conditions, obey the traffic laws and do not use the phone while riding.", "Ce sont des estimations et des aides : elles ne remplacent pas ton attention. Vérifie toujours les conditions réelles de la route et de la météo, respecte le code de la route et n'utilise pas le téléphone en roulant.", "Das sind Schätzungen und Hilfen: Sie ersetzen nicht deine Aufmerksamkeit. Prüfe immer die tatsächlichen Straßen- und Wetterbedingungen, beachte die Verkehrsregeln und nutze das Telefon nicht beim Fahren.", "Son estimaciones y ayudas: no sustituyen tu atención. Comprueba siempre las condiciones reales de la carretera y del tiempo, respeta el código de circulación y no uses el teléfono mientras conduces.")
FINAL = {'h': T('Pronto a partire?', 'Ready to ride?', 'Prêt à rouler ?', 'Bereit zur Abfahrt?', '¿Listo para rodar?'),
         'p': T("IDQ Biker Maps arriva presto su Google Play. Intanto leggi tutte le funzioni e l'informativa sulla privacy.", "IDQ Biker Maps is coming soon on Google Play. Meanwhile read all the features and the privacy policy.", "IDQ Biker Maps arrive bientôt sur Google Play. En attendant, lis toutes les fonctions et la politique de confidentialité.", "IDQ Biker Maps kommt bald bei Google Play. Lies in der Zwischenzeit alle Funktionen und die Datenschutzerklärung.", "IDQ Biker Maps llega pronto a Google Play. Mientras tanto lee todas las funciones y la política de privacidad."),
         'f': T('Tutte le funzioni (guida completa)', 'All features (full guide)', 'Toutes les fonctions (guide complet)', 'Alle Funktionen (vollständige Anleitung)', 'Todas las funciones (guía completa)'),
         'pr': T('Informativa sulla privacy', 'Privacy policy', 'Politique de confidentialité', 'Datenschutzerklärung', 'Política de privacidad')}

CSS = r"""
:root{--bg:#07070a;--bg2:#0e0e13;--tx:#f4f4f6;--mu:#a9a9b4;--ac:#ff7a00;--ac2:#2f8cff;--card:#14141a;--bd:#2a2a33}
*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:70px}
body{margin:0;background:var(--bg);color:var(--tx);font:17px/1.65 system-ui,-apple-system,"Segoe UI",Roboto,sans-serif}
a{color:var(--ac)}b{color:#fff}
.wrap{max-width:1080px;margin:0 auto;padding:0 20px}
header.top{position:sticky;top:0;z-index:20;background:rgba(7,7,10,.88);backdrop-filter:blur(10px);border-bottom:1px solid var(--bd)}
header.top .wrap{display:flex;gap:14px;align-items:center;justify-content:space-between;flex-wrap:wrap;padding-top:10px;padding-bottom:10px}
.brand{display:flex;align-items:center;gap:10px;font-weight:800;letter-spacing:.2px;text-decoration:none;color:var(--tx)}
.brand img{width:38px;height:38px;border-radius:50%}.brand span em{font-style:normal;color:var(--ac)}
nav.menu{display:flex;gap:4px;flex-wrap:wrap}nav.menu a{color:var(--mu);text-decoration:none;font-size:15px;padding:6px 10px;border-radius:8px}nav.menu a:hover{color:#fff;background:var(--card)}
.lingue button{border:1px solid var(--bd);background:var(--card);color:var(--tx);border-radius:999px;padding:5px 11px;margin:2px;cursor:pointer;font:inherit;font-size:13px}
.lingue button.on{background:var(--ac);color:#000;border-color:var(--ac);font-weight:700}
.hero{position:relative;overflow:hidden;text-align:center;padding:64px 0 56px;background:radial-gradient(ellipse at 50% -10%,#16294a 0%,#07070a 68%)}
.hero svg.strada{position:absolute;left:50%;bottom:-6px;transform:translateX(-50%);width:min(1200px,160%);opacity:.5;pointer-events:none}
.hero .wrap{position:relative}
.hero img.logo{width:min(250px,60vw);height:auto;border-radius:50%;box-shadow:0 0 0 3px var(--ac),0 14px 60px rgba(255,122,0,.4)}
.tag{display:inline-block;margin:22px 0 4px;color:var(--ac);font-weight:700;letter-spacing:.14em;text-transform:uppercase;font-size:13px}
.hero h1{font-size:clamp(34px,7vw,62px);line-height:1.08;margin:6px 0 14px;font-weight:900}
.hero h1 br+*{}
.hero p.lead{max-width:720px;margin:0 auto;color:#d3d3dc;font-size:clamp(17px,2.4vw,20px)}
.btns{display:flex;gap:12px;justify-content:center;flex-wrap:wrap;margin-top:26px}
.btn{display:inline-block;border-radius:999px;padding:13px 26px;font-weight:700;text-decoration:none}
.btn.p{background:var(--ac);color:#000}.btn.s{border:2px solid var(--ac2);color:#fff}.btn.p.off{cursor:default;box-shadow:0 0 0 0 rgba(255,122,0,.6);animation:pulsa 2.4s infinite}
a.btn.s{margin:0}
.piattaforme{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:14px}
.piatt{background:var(--card);border:1px dashed var(--bd);border-radius:16px;padding:16px 20px}.piatt.on{border:1px solid var(--ac2)}
.piatt b{display:block;font-size:19px;margin-bottom:4px}.piatt span{color:var(--mu);font-size:15px}

.tel{width:min(250px,64vw);aspect-ratio:450/872;border:7px solid #20202a;border-radius:34px;overflow:hidden;background:#000;box-shadow:0 18px 50px rgba(0,0,0,.6),0 0 0 1px #3a3a46;position:relative;flex:none}
.tel::before{content:"";position:absolute;top:7px;left:50%;transform:translateX(-50%);width:34%;height:14px;border-radius:9px;background:#000;z-index:2}
.tel video,.tel img{width:100%;height:100%;object-fit:cover;display:block}
.tels{display:flex;gap:22px;justify-content:center;align-items:flex-start;flex-wrap:wrap}
.tels figure,.gall figure{margin:0;text-align:center}.tels figcaption,.gall figcaption{margin-top:12px;font-size:14px;color:var(--mu);max-width:250px}
.tels figure:nth-child(2) .tel{margin-top:34px}
.forti{padding-top:70px}
.riga{display:grid;grid-template-columns:1.05fr 1fr;gap:54px;align-items:center;padding:46px 0;border-top:1px solid var(--bd)}
.riga:first-of-type{border-top:0}.riga.rev .testo{order:2}
.etichetta{display:inline-block;color:var(--ac);font-weight:800;letter-spacing:.14em;text-transform:uppercase;font-size:13px}
.riga h3{font-size:clamp(26px,3.6vw,38px);line-height:1.12;margin:6px 0 14px;font-weight:900}
.riga p.t{color:#d3d3dc;font-size:18px;margin:0 0 16px}
.riga ul{list-style:none;margin:0;padding:0}.riga li{position:relative;padding:7px 0 7px 28px;color:#e6e6ec}
.riga li::before{content:"";position:absolute;left:3px;top:15px;width:10px;height:10px;border-radius:3px;background:var(--ac);transform:rotate(45deg)}
.senza{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:16px;margin-top:34px}
.senza div{background:linear-gradient(160deg,#17171f,#101016);border:1px solid var(--bd);border-top:3px solid var(--ac2);border-radius:16px;padding:18px 20px}.senza b{display:block;color:var(--ac);margin-bottom:4px;font-size:18px}.senza span{color:#cfcfd8;font-size:15.5px}
.gall{display:flex;gap:22px;overflow-x:auto;padding:6px 4px 22px;scroll-snap-type:x mandatory;-webkit-overflow-scrolling:touch}.gall figure{scroll-snap-align:center}
.gall::-webkit-scrollbar{height:8px}.gall::-webkit-scrollbar-thumb{background:#333;border-radius:4px}
.hero-tel{margin-top:44px}
.tel .l,.cartw .l{display:none!important}
html[data-l=it] .tel .l[data-l=it],html[data-l=en] .tel .l[data-l=en],html[data-l=fr] .tel .l[data-l=fr],html[data-l=de] .tel .l[data-l=de],html[data-l=es] .tel .l[data-l=es],html[data-l=it] .cartw .l[data-l=it],html[data-l=en] .cartw .l[data-l=en],html[data-l=fr] .cartw .l[data-l=fr],html[data-l=de] .cartw .l[data-l=de],html[data-l=es] .cartw .l[data-l=es]{display:block!important}
.cart{width:min(250px,64vw);height:auto;border-radius:22px;border:1px solid #3a3a46;box-shadow:0 18px 50px rgba(0,0,0,.6);display:block}.riga .cart{width:min(212px,42vw)}
.riga .tel{width:min(212px,42vw)}.riga .tels{flex-wrap:nowrap;gap:18px}.riga .tels figcaption{max-width:212px}
@media(max-width:800px){.hero-tel{flex-wrap:nowrap;overflow-x:auto;justify-content:flex-start;scroll-snap-type:x mandatory;padding:0 18px 10px}.hero-tel figure{scroll-snap-align:center}.hero-tel .tel{width:54vw}.hero-tel figure:nth-child(2) .tel{margin-top:0}.riga{grid-template-columns:1fr;gap:26px}.riga.rev .testo{order:0}.tels figure:nth-child(2) .tel{margin-top:0}}
@keyframes pulsa{70%{box-shadow:0 0 0 16px rgba(255,122,0,0)}100%{box-shadow:0 0 0 0 rgba(255,122,0,0)}}
.chips{display:flex;gap:8px;justify-content:center;flex-wrap:wrap;margin-top:24px}.chips>span{border:1px solid var(--bd);background:rgba(20,20,26,.8);border-radius:999px;padding:5px 14px;font-size:14px;color:#dedee6}
.chips>span::before{content:"";display:inline-block;width:8px;height:8px;border-radius:50%;background:var(--ac2);margin-right:8px}
.nums{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:0;border-block:1px solid var(--bd);background:var(--bg2)}
.nums div{padding:26px 16px;text-align:center;border-right:1px solid var(--bd)}.nums div:last-child{border-right:0}
.nums b{display:block;font-size:clamp(30px,5vw,44px);color:var(--ac);line-height:1.1;font-weight:900}.nums span{color:var(--mu);font-size:15px}
section{padding:60px 0}
h2.t{font-size:clamp(26px,4.4vw,38px);margin:0 0 8px;font-weight:900;line-height:1.15}h2.t::after{content:"";display:block;width:64px;height:5px;border-radius:3px;background:linear-gradient(90deg,var(--ac),var(--ac2));margin-top:12px}
p.sub{color:var(--mu);max-width:760px;margin:12px 0 30px}
.aree{display:grid;grid-template-columns:repeat(auto-fit,minmax(310px,1fr));gap:18px}
.area{background:var(--card);border:1px solid var(--bd);border-radius:20px;padding:22px;position:relative;overflow:hidden}
.area::before{content:"";position:absolute;left:0;top:0;bottom:0;width:4px;background:linear-gradient(var(--ac),var(--ac2))}
.area .ic{color:var(--ac);display:flex;align-items:center;gap:10px;font-weight:800;text-transform:uppercase;letter-spacing:.1em;font-size:13px}
.area h3{margin:8px 0 12px;font-size:22px;line-height:1.2}
.area ul{margin:0;padding:0;list-style:none}.area li{position:relative;padding:8px 0 8px 22px;border-top:1px solid #23232b;color:#d6d6de;font-size:15.5px}
.area li::before{content:"";position:absolute;left:2px;top:17px;width:9px;height:9px;border-radius:2px;background:var(--ac2);transform:rotate(45deg)}
.steps{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:18px;counter-reset:s}
.step{background:linear-gradient(160deg,#17171f,#101016);border:1px solid var(--bd);border-radius:20px;padding:24px;position:relative}
.step::before{counter-increment:s;content:counter(s);position:absolute;right:18px;top:6px;font-size:72px;font-weight:900;color:rgba(255,122,0,.16);line-height:1}
.step h3{margin:0 0 8px;font-size:20px;color:#fff;max-width:85%}.step p{margin:0;color:#cfcfd8;font-size:15.5px}
details.g{background:var(--card);border:1px solid var(--bd);border-radius:16px;margin:10px 0;overflow:hidden}
details.g summary{cursor:pointer;padding:16px 20px;font-weight:700;font-size:18px;list-style:none;display:flex;justify-content:space-between;gap:12px;align-items:center}
details.g summary::-webkit-details-marker{display:none}details.g summary::after{content:"+";color:var(--ac);font-size:26px;font-weight:400;line-height:1}
details.g[open] summary{border-bottom:1px solid var(--bd)}details.g[open] summary::after{content:"–"}
details.g ol{margin:0;padding:18px 22px 20px 52px;counter-reset:n;list-style:none}
details.g ol li{position:relative;margin:0 0 12px;color:#d9d9e1}details.g ol li::before{counter-increment:n;content:counter(n);position:absolute;left:-34px;top:1px;width:24px;height:24px;border-radius:50%;background:var(--ac);color:#000;font-weight:800;font-size:13px;text-align:center;line-height:24px}
details.f{border-bottom:1px solid var(--bd);padding:2px 0}details.f summary{cursor:pointer;padding:14px 0;font-weight:700;font-size:18px;list-style:none}details.f summary::-webkit-details-marker{display:none}
details.f summary::before{content:"+";color:var(--ac2);font-weight:900;margin-right:12px}details.f[open] summary::before{content:"–"}details.f p{margin:0 0 16px 24px;color:#cfcfd8}
.warn{border:1px solid #5a3a10;background:rgba(255,122,0,.07);border-radius:14px;padding:16px 20px;color:#f0d9bd;font-size:15px;margin-top:28px}
.final{text-align:center;background:radial-gradient(ellipse at 50% 120%,#1b2f55 0%,#07070a 65%);border-top:1px solid var(--bd)}
.final p{color:#cfcfda;max-width:640px;margin:0 auto 22px}
footer{border-top:1px solid var(--bd);padding:26px 20px;text-align:center;color:var(--mu);font-size:15px}footer a{margin:0 8px}
.l{display:none}
html[data-l=it] .l[data-l=it],html[data-l=en] .l[data-l=en],html[data-l=fr] .l[data-l=fr],html[data-l=de] .l[data-l=de],html[data-l=es] .l[data-l=es]{display:block}
html[data-l=it] span.l[data-l=it],html[data-l=en] span.l[data-l=en],html[data-l=fr] span.l[data-l=fr],html[data-l=de] span.l[data-l=de],html[data-l=es] span.l[data-l=es]{display:inline}
@media(max-width:640px){nav.menu{display:none}.hero{padding:44px 0 40px}.nums div{border-right:0;border-bottom:1px solid var(--bd)}section{padding:44px 0}}
@media(prefers-reduced-motion:reduce){.btn.p.off{animation:none}html{scroll-behavior:auto}}
"""
STRADA = '<svg class="strada" viewBox="0 0 1200 200" preserveAspectRatio="none" aria-hidden="true"><path d="M-20 170 C 160 60, 280 190, 440 110 S 700 40, 820 120 S 1040 190, 1230 60" fill="none" stroke="#1b1b24" stroke-width="64" stroke-linecap="round"/><path d="M-20 170 C 160 60, 280 190, 440 110 S 700 40, 820 120 S 1040 190, 1230 60" fill="none" stroke="#ff7a00" stroke-width="4" stroke-dasharray="26 22" stroke-linecap="round"/></svg>'

def L(d, tag='div', extra=''):
    return ''.join(f'<{tag} class="l" data-l="{l}"{extra}>{d[l]}</{tag}>' for l in LG)
def S(d): return ''.join(f'<span class="l" data-l="{l}">{d[l]}</span>' for l in LG)

STILL = {'giri': 'giro-anello', 'curve': 'curve', 'allarme': 'allarme', 'navigazione': 'navigazione'}   # lingua diversa dall'italiano: al posto del video, la schermata nella sua lingua
def percorso_img(f, l): return f'immagini/app/{f}.jpg' if l == 'it' else f'immagini/app/{l}/{f}.jpg'

def media(m):
    """Schermata o video dentro una cornice da telefono. I video sono in italiano; nelle altre lingue si vede la schermata tradotta."""
    tipo, f, cap = m
    if tipo == 'card':   # immagine intera (non uno schermo del telefono): cartolina con bordo arrotondato, nella lingua scelta
        imgs = ''.join(f'<img class="cart l" data-l="{l}" src="{percorso_img(f, l)}" alt="" loading="lazy">' for l in LG)
        return f'<figure><div class="cartw">{imgs}</div><figcaption>{S(cap)}</figcaption></figure>'
    if tipo == 'video':
        inner = f'<video class="l" data-l="it" muted loop playsinline preload="none" poster="immagini/app/{f}-poster.jpg" data-src="immagini/app/{f}.mp4"></video>'
        inner += ''.join(f'<img class="l" data-l="{l}" src="{percorso_img(STILL[f], l)}" alt="" loading="lazy">' for l in LG if l != 'it')
        return f'<figure><div class="tel" style="background:#000 url(immagini/app/{f}-poster.jpg) center/cover no-repeat">{inner}</div><figcaption>{S(cap)}</figcaption></figure>'
    inner = ''.join(f'<img class="l" data-l="{l}" src="{percorso_img(f, l)}" alt="" loading="lazy">' for l in LG)
    return f'<figure><div class="tel">{inner}</div><figcaption>{S(cap)}</figcaption></figure>'

def sezione_forti():
    righe = ''
    for i, (fid, et, tit, txt, punti, med) in enumerate(FORTI):
        righe += (f'<div class="riga{" rev" if i % 2 else ""}" id="f-{fid}"><div class="testo"><span class="etichetta">{S(et)}</span><h3>{S(tit)}</h3><p class="t">{S(txt)}</p><ul>'
                  + ''.join(f'<li>{S(x)}</li>' for x in punti) + '</ul></div><div class="tels">' + ''.join(media(m) for m in med) + '</div></div>')
    senza = '<div class="senza">' + ''.join(f'<div><b>{S(t)}</b><span>{S(x)}</span></div>' for t, x in SENZA) + '</div>'
    return f'<section id="forti" class="forti"><div class="wrap"><h2 class="t">{S(FORTI_H)}</h2><p class="sub">{S(FORTI_S)}</p>{righe}{senza}</div></section>'

def sezione_galleria():
    return f'<section id="galleria" style="background:var(--bg2);border-block:1px solid var(--bd)"><div class="wrap"><h2 class="t">{S(GALL_H)}</h2><div class="gall" style="margin-top:26px">' + ''.join(media(m) for m in GALL) + '</div></div></section>'

def hero_telefoni():
    return '<div class="tels hero-tel">' + ''.join(media(m) for m in (('video', 'navigazione', T('', '', '', '', '')), ('video', 'giri', T('', '', '', '', '')), ('video', 'curve', T('', '', '', '', '')))) + '</div>'

def pagina():
    nav = ''.join(f'<a href="#{i}">{S(t)}</a>' for i, t in NAV)
    langs = ''.join(f'<button data-l="{l}">{l.upper()}</button>' for l in LG)
    chips = ''.join(f'<span>{S(c)}</span>' for c in CHIPS)
    nums = ''.join(f'<div><b>{n}</b><span>{S(t)}</span></div>' for n, t in NUMERI)
    aree = ''
    for ic, nome, titolo, righe in AREE:
        aree += f'<article class="area"><div class="ic">{ico(ic)}{S(nome)}</div><h3>{S(titolo)}</h3><ul>' + ''.join(f'<li>{S(r)}</li>' for r in righe) + '</ul></article>'
    start = ''.join(f'<div class="step"><h3>{S(t)}</h3><p>{S(p)}</p></div>' for t, p in START)
    guide = ''
    for gid, tit, passi in GUIDE:
        blocchi = ''.join(f'<ol class="l" data-l="{l}">' + ''.join(f'<li>{p}</li>' for p in passi[l]) + '</ol>' for l in LG)
        guide += f'<details class="g" id="g-{gid}"><summary>{S(tit)}</summary>{blocchi}</details>'
    prova = ''.join(f'<div class="step"><h3>{S(t)}</h3><p>{S(p)}</p></div>' for t, p in PROVA)
    piatt = ''.join(f'<div class="piatt{" on" if ok else ""}"><b>{S(n)}</b><span>{S(st)}</span></div>' for n, st, ok in PIATTAFORME)
    faq = ''.join(f'<details class="f"><summary>{S(q)}</summary><p>{S(a)}</p></details>' for q, a in FAQ)
    desc = HERO['p']['en'].replace('"', '&quot;')
    return f'''<!doctype html>
<html lang="it" data-l="it"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>IDQ Biker Maps</title>
<meta name="description" content="IDQ Biker Maps: {desc}">
<meta name="theme-color" content="#07070a">
<link rel="icon" href="immagini/icona.png">
<style>{CSS}</style></head><body>
<header class="top"><div class="wrap"><a class="brand" href="#"><img src="immagini/icona.png" alt=""><span><em>IDQ</em> Biker Maps</span></a>
<nav class="menu">{nav}</nav><div class="lingue">{langs}</div></div></header>
<section class="hero" style="padding-bottom:70px">{STRADA}<div class="wrap"><img class="logo" src="immagini/logo.png" alt="IDQ Biker Maps">
<div class="tag">{S(HERO['tag'])}</div><h1>{L(HERO['h1'], 'span')}</h1>
<p class="lead">{S(HERO['p'])}</p>
<div class="btns"><span class="btn p off">{S(HERO['soon'])}</span><a class="btn s" href="#funzioni">{S(HERO['cta2'])}</a></div>
<div class="chips">{chips}</div>{hero_telefoni()}</div></section>
<div class="nums">{nums}</div>
{sezione_forti()}
{sezione_galleria()}
<section id="funzioni"><div class="wrap"><h2 class="t">{S(FEAT_H)}</h2><p class="sub">{S(FEAT_S)}</p><div class="aree">{aree}</div>
<div class="warn">{S(WARN)}</div></div></section>
<section id="prova"><div class="wrap"><h2 class="t">{S(PROVA_H)}</h2><p class="sub">{S(PROVA_S)}</p><div class="steps">{prova}</div><h3 style="margin:38px 0 12px">{S(PIATTAFORME_H)}</h3><div class="piattaforme">{piatt}</div></div></section>
<section id="inizio" style="background:var(--bg2);border-block:1px solid var(--bd)"><div class="wrap"><h2 class="t">{S(START_H)}</h2><div class="steps" style="margin-top:26px">{start}</div></div></section>
<section id="guide"><div class="wrap"><h2 class="t">{S(GUIDE_H)}</h2><p class="sub">{S(GUIDE_S)}</p>{guide}</div></section>
<section id="faq" style="background:var(--bg2);border-block:1px solid var(--bd)"><div class="wrap"><h2 class="t">{S(FAQ_H)}</h2><div style="margin-top:22px">{faq}</div></div></section>
<section class="final"><div class="wrap"><h2 class="t" style="display:inline-block">{S(FINAL['h'])}</h2><p>{S(FINAL['p'])}</p>
<div class="btns"><a class="btn p" href="funzioni.html">{S(FINAL['f'])}</a><a class="btn s" href="privacy.html">{S(FINAL['pr'])}</a></div></div></section>
<footer><a href="funzioni.html">{S(FINAL['f'])}</a> · <a href="privacy.html">{S(FINAL['pr'])}</a><br><span style="font-size:13px">© IDQ Developer · IDQ Biker Maps</span></footer>
<script>
(function(){{
 var L=["it","en","fr","de","es"],q=(location.search.match(/[?&]lang=(\\w\\w)/)||[])[1];
 var s=null;try{{s=localStorage.getItem("l")}}catch(e){{}}
 var n=((navigator.language||"it").slice(0,2));
 var l=L.indexOf(q)>=0?q:(L.indexOf(s)>=0?s:(L.indexOf(n)>=0?n:"it"));
 function set(x){{document.documentElement.setAttribute("data-l",x);document.documentElement.lang=x;try{{localStorage.setItem("l",x)}}catch(e){{}}
  document.querySelectorAll(".lingue button").forEach(function(b){{b.classList.toggle("on",b.dataset.l===x)}})}}
 document.querySelectorAll(".lingue button").forEach(function(b){{b.onclick=function(){{set(b.dataset.l)}}}});
 set(l);
 if(location.hash){{var d=document.querySelector(location.hash);if(d&&d.tagName==="DETAILS")d.open=true}}
 var V=document.querySelectorAll("video[data-src]");
 if("IntersectionObserver" in window){{var io=new IntersectionObserver(function(es){{es.forEach(function(e){{var v=e.target;if(e.isIntersecting){{if(!v.src)v.src=v.dataset.src;var p=v.play();if(p&&p.catch)p.catch(function(){{}})}}else v.pause()}})}},{{threshold:.35}});V.forEach(function(v){{io.observe(v)}})}}else V.forEach(function(v){{v.src=v.dataset.src;v.autoplay=true}});
}})();
</script></body></html>'''

if __name__ == '__main__':
    open('index.html', 'w', encoding='utf-8').write(pagina()); print('index.html scritto')
